const event = $input.first().json.body ?? $input.first().json;
const required = ['invoice_id', 'payee', 'amount', 'currency', 'reason'];
for (const field of required) {
  if (event[field] === undefined || event[field] === null || String(event[field]).trim() === '') {
    throw new Error(`Missing required invoice field: ${field}`);
  }
}
const amount = Number(event.amount);
if (!Number.isFinite(amount) || amount <= 0) throw new Error('Invoice amount must be positive');
const invoiceId = String(event.invoice_id).trim();
return [{ json: {
  idempotencyKey: `invoice:${invoiceId}`,
  payload: {
    payee: String(event.payee).trim(),
    amount: String(event.amount),
    currency: String(event.currency).trim().toUpperCase(),
    issuer: event.issuer ? String(event.issuer).trim() : null,
    network: event.network ?? 'testnet',
    reason: String(event.reason).trim(),
    source: 'invoice',
    source_reference: invoiceId
  }
} }];
